package main

import (
	"errors"
	"os"
	"text/template"
)

func main() {
	fmap := template.FuncMap{
		"strings": func() any {
			return map[string]any{
				"Boom": func() (string, error) { return "", errors.New("kablam") },
			}
		},
	}
	t := template.Must(template.New("<arg>").Funcs(fmap).Parse(`{{ strings.Boom }}`))
	err := t.Execute(os.Stdout, nil)
	if err != nil {
		os.Stderr.WriteString("ERR: " + err.Error() + "\n")
	}
}
EOF
