// nArgs parses the arguments of FindAll/Split: either (expression, input)
// or (expression, n, input). The n conversion is validated before the
// expression is compiled, matching the reference tool's error precedence.
func nArgs(args []any) (expression any, num int, input any, err error) {
	if len(args) != 2 && len(args) != 3 {
		return nil, 0, nil, fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args))
	}
	expression = args[0]
	num = -1
	input = args[len(args)-1]
	if len(args) == 3 {
		i64, err := toInt64(args[1])
		if err != nil {
			return nil, 0, nil, fmt.Errorf("n must be an integer: %w", err)
		}
		num = int(i64)
	}
	return expression, num, input, nil
}

