		{"message on failure", `{{ assert "something horrible happened" false }}`, "", "assertion failed: something horrible happened"},
		{"empty message on failure", `{{ assert "" false }}`, "", "assertion failed"},
		{"non-string message bool", `{{ assert true true }}`, "", "at <1>: expected string; found bool"},
		{"non-string message int", `{{ assert 42 true }}`, "", "at <1>: expected string; found int"},
		{"non-string message float", `{{ assert 1.5 false }}`, "", "at <1>: expected string; found float64"},
		{"non-string message nil", `{{ assert nil false }}`, "", "at <1>: expected string; found <nil>"},
		{"too many args", `{{ assert 1 2 3 }}`, "", "wrong number of args: want 1 or 2, got 3"},
		{"zero args panics", `{{ assert }}`, "", "runtime error: index out of range [-1]"},
		{"message is first arg in pipeline order", `{{ assert "yes" "msg ignored?" }}`, "", "assertion failed: yes"},
	})
}

func TestFail(t *testing.T) {
	runCases(t, []renderCase{
		{"no message", `{{ fail }}`, "", "template generation failed"},
		{"namespace form", `{{ test.Fail }}`, "", "template generation failed"},
		{"with message", `{{ fail "something is wrong!" }}`, "", "template generation failed: something is wrong!"},
		{"namespace with message", `{{ test.Fail "boom" }}`, "", "template generation failed: boom"},
		{"empty message", `{{ fail "" }}`, "", "template generation failed"},
		{"int message", `{{ fail 42 }}`, "", "template generation failed: 42"},
		{"float message", `{{ fail 4.2 }}`, "", "template generation failed: 4.2"},
		{"float whole message", `{{ fail 2.0 }}`, "", "template generation failed: 2"},
		{"bool message", `{{ fail true }}`, "", "template generation failed: true"},
		{"nil message", `{{ fail nil }}`, "", "template generation failed: nil"},
		{"too many args", `{{ fail "a" "b" }}`, "", "wrong number of args: want 0 or 1, got 2"},
	})
}

func TestIsKind(t *testing.T) {
	runCases(t, []renderCase{
		{"string", `{{ isKind "string" "x" }}`, "true", ""},
		{"string false", `{{ isKind "string" 42 }}`, "false", ""},
		{"int", `{{ isKind "int" 42 }}`, "true", ""},
		{"int false for float", `{{ isKind "int" 4.2 }}`, "false", ""},
		{"float64", `{{ isKind "float64" 4.2 }}`, "true", ""},
		{"float64 false for int", `{{ isKind "float64" 42 }}`, "false", ""},
		{"bool", `{{ isKind "bool" true }}`, "true", ""},
		{"number int", `{{ isKind "number" 42 }}`, "true", ""},
		{"number float", `{{ isKind "number" 4.2 }}`, "true", ""},
		{"number false for string", `{{ isKind "number" "42" }}`, "false", ""},
		{"number false for bool", `{{ isKind "number" true }}`, "false", ""},
		{"invalid nil", `{{ isKind "invalid" nil }}`, "true", ""},
		{"invalid non-nil", `{{ isKind "invalid" 42 }}`, "false", ""},
		{"unknown kind", `{{ isKind "bogus" 1 }}`, "false", ""},
		{"case sensitive", `{{ isKind "String" "x" }}`, "false", ""},
		{"int64 false for int", `{{ isKind "int64" 42 }}`, "false", ""},
		{"namespace form", `{{ test.IsKind "number" 4.2 }}`, "true", ""},
		{"pipeline", `{{ "x" | isKind "string" }}`, "true", ""},
	})
}

func TestKind(t *testing.T) {
	runCases(t, []renderCase{
		{"string", `{{ kind "hello world" }}`, "string", ""},
		{"int", `{{ kind 42 }}`, "int", ""},
		{"float64", `{{ kind 4.2 }}`, "float64", ""},
		{"bool", `{{ kind true }}`, "bool", ""},
		{"nil", `{{ kind nil }}`, "invalid", ""},
		{"numeric string", `{{ kind "1" }}`, "string", ""},
		{"namespace form", `{{ test.Kind 42 }}`, "int", ""},
		{"pipeline", `{{ "x" | kind }}`, "string", ""},
	})
}

func TestRequired(t *testing.T) {
	runCases(t, []renderCase{
		{"passes string through", `{{ required "msg" "val" }}`, "val", ""},
		{"one arg passes through", `{{ required "x" }}`, "x", ""},
		{"empty message passes through", `{{ required "" "x" }}`, "x", ""},
		{"int passes", `{{ required "msg" 42 }}`, "42", ""},
		{"int zero passes", `{{ required "msg" 0 }}`, "0", ""},
		{"bool false passes", `{{ required "msg" false }}`, "false", ""},
		{"float zero passes", `{{ required "msg" 0.0 }}`, "0", ""},
		{"whitespace string passes", `{{ required "msg" " " }}`, " ", ""},
		{"empty string fails", `{{ required "msg" "" }}`, "", "msg"},
		{"nil fails", `{{ required "msg" nil }}`, "", "msg"},
		{"empty string no message", `{{ required "" }}`, "", "can not render template: a required value was not set"},
		{"nil no message", `{{ required nil }}`, "", "can not render template: a required value was not set"},
		{"empty message empty value", `{{ required "" "" }}`, "", "can not render template: a required value was not set"},
		{"non-string message", `{{ required 42 "" }}`, "", "at <1>: expected string; found int"},
		{"zero args", `{{ required }}`, "", "wrong number of args: want 1 or 2, got 0"},
		{"three args", `{{ required "a" "b" "c" }}`, "", "wrong number of args: want 1 or 2, got 3"},
		{"namespace form", `{{ test.Required "m" "x" }}`, "x", ""},
		{"pipeline", `{{ "x" | test.Required "m" }}`, "x", ""},
	})
}

func TestTernary(t *testing.T) {
	runCases(t, []renderCase{
		{"false condition", `{{ ternary "FOO" "BAR" false }}`, "BAR", ""},
		{"yes condition", `{{ ternary "FOO" "BAR" "yes" }}`, "FOO", ""},
		{"true condition", `{{ ternary "A" "B" true }}`, "A", ""},
		{"no condition", `{{ ternary "A" "B" "no" }}`, "B", ""},
		{"nil condition", `{{ ternary "A" "B" nil }}`, "B", ""},
		{"int 2 condition false", `{{ ternary "A" "B" 2 }}`, "B", ""},
		{"int 1 condition true", `{{ ternary "A" "B" 1 }}`, "A", ""},
		{"returns int", `{{ ternary 1 2 true }}`, "1", ""},
		{"returns float", `{{ ternary 1.5 2.5 1 }}`, "1.5", ""},
		{"namespace form", `{{ test.Ternary "x" "y" "TRUE" }}`, "x", ""},
		{"pipeline", `{{ "yes" | ternary "T" "F" }}`, "T", ""},
	})
}

// TestWrongArgCounts covers engine-generated arity errors for the
// non-variadic functions; the exact text comes from text/template itself.
func TestWrongArgCounts(t *testing.T) {
	runCases(t, []renderCase{
		{"kind zero args", `{{ kind }}`, "", "wrong number of args for kind: want 1 got 0"},
		{"kind two args", `{{ kind 1 2 }}`, "", "wrong number of args for kind: want 1 got 2"},
		{"isKind one arg", `{{ isKind "int" }}`, "", "wrong number of args for isKind: want 2 got 1"},
		{"isKind three args", `{{ isKind "int" 1 2 }}`, "", "wrong number of args for isKind: want 2 got 3"},
		{"ternary two args", `{{ ternary 1 2 }}`, "", "wrong number of args for ternary: want 3 got 2"},
		{"ternary four args", `{{ ternary 1 2 3 4 }}`, "", "wrong number of args for ternary: want 3 got 4"},
		{"isKind non-string kind", `{{ isKind 42 42 }}`, "", "expected string; found 42"},
	})
}

