package uuid

import (
	"bytes"
	"regexp"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"uuid": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func mustRender(t *testing.T, tmpl string) string {
	t.Helper()
	out, err := render(t, tmpl)
	if err != nil {
		t.Fatalf("render(%q) failed: %v", tmpl, err)
	}
	return out
}

var canonicalRe = regexp.MustCompile(`^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)

func TestNil(t *testing.T) {
	out := mustRender(t, `{{ uuid.Nil }}`)
	if out != "00000000-0000-0000-0000-000000000000" {
		t.Errorf("uuid.Nil = %q, want nil UUID", out)
	}
}

func TestV4(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 10; i++ {
		out := mustRender(t, `{{ uuid.V4 }}`)
		if !canonicalRe.MatchString(out) {
			t.Fatalf("uuid.V4 = %q, not canonical form", out)
		}
		if out[14] != '4' {
			t.Errorf("uuid.V4 = %q, version nibble is %q, want '4'", out, out[14])
		}
		if !strings.ContainsRune("89ab", rune(out[19])) {
			t.Errorf("uuid.V4 = %q, variant nibble is %q, want one of 8,9,a,b", out, out[19])
		}
		if seen[out] {
			t.Errorf("uuid.V4 returned duplicate %q", out)
		}
		seen[out] = true
	}
}

func TestV1(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 10; i++ {
		out := mustRender(t, `{{ uuid.V1 }}`)
		if !canonicalRe.MatchString(out) {
			t.Fatalf("uuid.V1 = %q, not canonical form", out)
		}
		if out[14] != '1' {
			t.Errorf("uuid.V1 = %q, version nibble is %q, want '1'", out, out[14])
		}
		if !strings.ContainsRune("89ab", rune(out[19])) {
			t.Errorf("uuid.V1 = %q, variant nibble is %q, want one of 8,9,a,b", out, out[19])
		}
		if seen[out] {
			t.Errorf("uuid.V1 returned duplicate %q", out)
		}
		seen[out] = true
	}
}

func TestIsValid(t *testing.T) {
	tests := []struct {
		tmpl string
		want string
	}{
		{`{{ uuid.IsValid "totally invalid" }}`, "false"},
		{`{{ if uuid.IsValid "totally invalid" }}valid{{ else }}invalid{{ end }}`, "invalid"},
		{`{{ uuid.IsValid "12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "urn:uuid:12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "URN:UUID:12345678-90ab-cdef-fedc-ba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "{12345678-90ab-cdef-fedc-ba9876543210}" }}`, "true"},
		{`{{ uuid.IsValid "1234567890abcdeffedcba9876543210" }}`, "true"},
		{`{{ uuid.IsValid "12345678-90ab-CDEF-FEDC-BA9876543210" }}`, "true"},
		{`{{ uuid.IsValid "" }}`, "false"},
		{`{{ uuid.IsValid "12345678-90ab-cdef-fedc-ba987654321" }}`, "false"},
		{`{{ uuid.IsValid "zzzzzzzz-90ab-cdef-fedc-ba9876543210" }}`, "false"},
		{`{{ uuid.IsValid "urn:uuid:12345678-90ab-cdef-fedc-ba98765432" }}`, "false"},
		// non-string inputs are coerced to strings first
		{`{{ uuid.IsValid 123 }}`, "false"},
		{`{{ uuid.IsValid true }}`, "false"},
		{`{{ uuid.IsValid 1.5 }}`, "false"},
		{`{{ uuid.IsValid nil }}`, "false"},
		// pipeline form
		{`{{ "12345678-90ab-cdef-fedc-ba9876543210" | uuid.IsValid }}`, "true"},
		{`{{ "nope" | uuid.IsValid }}`, "false"},
	}
	for _, tc := range tests {
		out, err := render(t, tc.tmpl)
		if err != nil {
			t.Errorf("render(%q) failed: %v", tc.tmpl, err)
			continue
		}
		if out != tc.want {
			t.Errorf("render(%q) = %q, want %q", tc.tmpl, out, tc.want)
		}
	}
}

func TestParse(t *testing.T) {
	const canonical = "c232ab00-9414-11ec-b3c8-9f6bdeced846"
	// every accepted input form parses to the same canonical UUID
	forms := []string{
		`"c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"C232AB00-9414-11EC-B3C8-9F6BDECED846"`,
		`"urn:uuid:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"URN:UUID:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"uRn:uUuD:c232ab00-9414-11ec-b3c8-9f6bdeced846"`,
		`"{c232ab00-9414-11ec-b3c8-9f6bdeced846}"`,
		`"c232ab00941411ecb3c89f6bdeced846"`,
		`"C232AB00941411ECB3C89F6BDECED846"`,
	}
	for _, form := range forms {
		tmpl := `{{ (uuid.Parse ` + form + `).String }}`
		out := mustRender(t, tmpl)
		if out != canonical {
			t.Errorf("render(%q) = %q, want %q", tmpl, out, canonical)
		}
	}

	// printing a parsed UUID directly uses its String method
	out := mustRender(t, `{{ uuid.Parse "c232ab00-9414-11ec-b3c8-9f6bdeced846" }}`)
	if out != canonical {
		t.Errorf("direct print = %q, want %q", out, canonical)
	}

	// pipeline form
	out = mustRender(t, `{{ "c232ab00-9414-11ec-b3c8-9f6bdeced846" | uuid.Parse }}`)
	if out != canonical {
		t.Errorf("pipeline = %q, want %q", out, canonical)
	}

	// doc examples
	out = mustRender(t, `{{ $u := uuid.Parse uuid.V4 }}{{ $u.Version }}, {{ $u.Variant}}`)
	if out != "VERSION_4, RFC4122" {
		t.Errorf("doc example = %q, want %q", out, "VERSION_4, RFC4122")
	}
	out = mustRender(t, `{{ (uuid.Parse "000001f5-4470-21e9-9b00-72000877c7b0").Domain }}`)
	if out != "Person" {
		t.Errorf("doc example = %q, want %q", out, "Person")
	}
}

func TestParsedUUIDMethods(t *testing.T) {
	const u = "c232ab00-9414-11ec-b3c8-9f6bdeced846"
	tests := []struct {
		tmpl string
		want string
	}{
		{`{{ (uuid.Parse "` + u + `").String }}`, "c232ab00-9414-11ec-b3c8-9f6bdeced846"},
		{`{{ (uuid.Parse "` + u + `").URN }}`, "urn:uuid:c232ab00-9414-11ec-b3c8-9f6bdeced846"},
		{`{{ (uuid.Parse "` + u + `").Version }}`, "VERSION_1"},
		{`{{ (uuid.Parse "` + u + `").Variant }}`, "RFC4122"},
		{`{{ (uuid.Parse "` + u + `").Time }}`, "138648505420000000"},
		{`{{ (uuid.Parse "` + u + `").ClockSequence }}`, "13256"},
		{`{{ (uuid.Parse "` + u + `").Domain }}`, "Domain200"},
		{`{{ (uuid.Parse "` + u + `").ID }}`, "3258100480"},
		{`{{ (uuid.Parse "` + u + `").NodeID }}`, "[159 107 222 206 216 70]"},
		{`{{ (uuid.Parse "` + u + `").Value }}`, "c232ab00-9414-11ec-b3c8-9f6bdeced846"},
		{`{{ (uuid.Parse "` + u + `").MarshalBinary }}`, "[194 50 171 0 148 20 17 236 179 200 159 107 222 206 216 70]"},
		{`{{ (uuid.Parse "` + u + `").MarshalText }}`, "[99 50 51 50 97 98 48 48 45 57 52 49 52 45 49 49 101 99 45 98 51 99 56 45 57 102 54 98 100 101 99 101 100 56 52 54]"},
		// variants
		{`{{ (uuid.Parse "ffffffff-ffff-ffff-ffff-ffffffffffff").Variant }}`, "Future"},
		{`{{ (uuid.Parse "ffffffff-ffff-ffff-8fff-ffffffffffff").Variant }}`, "RFC4122"},
		{`{{ (uuid.Parse "ffffffff-ffff-ffff-cfff-ffffffffffff").Variant }}`, "Microsoft"},
