		t.Fatalf("unexpected error: %v", err)
	}
	if got != "-rw-r--r-- 11 hi false" {
		t.Errorf("got %q, want %q", got, "-rw-r--r-- 11 hi false")
	}

	got, err = render(t, `{{ $s := file.Stat "foo" }}{{ $s.IsDir }} {{ $s.Name }}`)
	if err != nil {
