func TestWrite(t *testing.T) {
	cases := []struct {
		tmpl    string
		file    string // file to check, relative to root
		content string
	}{
		{`{{ file.Write "out.txt" "hello world" }}`, "out.txt", "hello world"},
		{`{{ "hello world" | file.Write "pipe.txt" }}`, "pipe.txt", "hello world"},
		{`{{ file.Write "sub2/deep/out.txt" "x" }}`, "sub2/deep/out.txt", "x"},
		{`{{ file.Write "n.txt" 42 }}`, "n.txt", "42"},
		{`{{ file.Write "f.txt" 1.5 }}`, "f.txt", "1.5"},
		{`{{ file.Write "f2.txt" 2.0 }}`, "f2.txt", "2"},
		{`{{ file.Write "t.txt" true }}`, "t.txt", "true"},
		{`{{ file.Write "nil.txt" nil }}`, "nil.txt", "nil"},
		{`{{ file.Write "m.txt" .data }}`, "m.txt", "map[a:1]"},
		{`{{ file.Write "w6.txt" "line1\nline2" }}`, "w6.txt", "line1\nline2"},
		{`{{ file.Write "sub2/../w7.txt" "ok" }}`, "w7.txt", "ok"},
		{`{{ file.Write "./w8.txt" "ok" }}`, "w8.txt", "ok"},
	}
	for _, c := range cases {
		tmpl := c.tmpl
		got, err := render(t, tmpl)
		if err != nil {
			t.Errorf("%s: unexpected error: %v", tmpl, err)
			continue
		}
		if got != "" {
			t.Errorf("%s: rendered %q, want empty output", tmpl, got)
		}
		b, err := os.ReadFile(filepath.Join(root, c.file))
		if err != nil {
			t.Errorf("%s: reading written file: %v", tmpl, err)
			continue
		}
		if string(b) != c.content {
			t.Errorf("%s: file content %q, want %q", tmpl, string(b), c.content)
		}
	}

	// map data via template data
	{
		tt, err := template.New("<arg>").Funcs(template.FuncMap{"file": func() any { return NS() }}).Parse(`{{ file.Write "map.txt" .data }}`)
		if err != nil {
			t.Fatal(err)
		}
		var buf bytes.Buffer
		if err := tt.Execute(&buf, map[string]any{"data": map[string]any{"a": 1}}); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		b, err := os.ReadFile(filepath.Join(root, "map.txt"))
		if err != nil {
			t.Fatal(err)
		}
		if string(b) != "map[a:1]" {
			t.Errorf("map data: got %q, want %q", string(b), "map[a:1]")
		}
	}

	// Write returns an empty string value
	got, err := render(t, `{{ printf "%v|%T" (file.Write "rv.txt" "x") (file.Write "rv2.txt" "x") }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != "|string" {
		t.Errorf("return value: got %q, want %q", got, "|string")
	}

	// overwrite an existing file, permissions preserved
	{
		target := filepath.Join(root, "over.txt")
		if err := os.WriteFile(target, []byte("old content here"), 0o640); err != nil {
			t.Fatal(err)
		}
		if _, err := render(t, `{{ file.Write "over.txt" "new" }}`); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		b, _ := os.ReadFile(target)
		if string(b) != "new" {
			t.Errorf("overwrite: got %q, want %q", string(b), "new")
		}
		fi, _ := os.Stat(target)
		if fi.Mode().Perm() != 0o640 {
			t.Errorf("overwrite: perm %v changed", fi.Mode().Perm())
		}
	}

	// absolute path inside the working directory is allowed
	abs := filepath.Join(root, "abs.txt")
	if _, err := render(t, `{{ file.Write "`+abs+`" "abs" }}`); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if b, _ := os.ReadFile(abs); string(b) != "abs" {
		t.Errorf("absolute in-cwd write failed")
	}

	// created directories have 0755 and files 0644 (umask permitting)
	fi, err := os.Stat(filepath.Join(root, "sub2", "deep"))
	if err != nil {
		t.Fatal(err)
	}
	if fi.Mode().Perm() != 0o755 {
		t.Errorf("dir perm: got %v, want drwxr-xr-x", fi.Mode().Perm())
	}
	fi, err = os.Stat(filepath.Join(root, "out.txt"))
	if err != nil {
		t.Fatal(err)
	}
	if fi.Mode().Perm() != 0o644 {
		t.Errorf("file perm: got %v, want -rw-r--r--", fi.Mode().Perm())
	}
}

func TestWriteErrors(t *testing.T) {
	outside := filepath.Dir(root) // parent of the working directory
	_ = outside
	errCases := []struct {
		tmpl string
		want string
	}{
		{
			`{{ file.Write "../escape.txt" "bad" }}`,
			"failed to open ../escape.txt: path ../escape.txt not contained by working directory " + root + " (rel: ../escape.txt)",
		},
		{
			`{{ file.Write "/etc/evil.txt" "bad" }}`,
			"failed to open /etc/evil.txt: path /etc/evil.txt not contained by working directory " + root + " (rel: " + mustRel(t, root, "/etc/evil.txt") + ")",
		},
		{
			`{{ file.Write "" "y" }}`,
			"failed to stat : stat : invalid argument",
		},
		{
			`{{ file.Write "hi/x" "y" }}`,
			"failed to stat hi/x: stat " + disp(filepath.Join(root, "hi", "x")) + ": not a directory",
		},
		{
			`{{ file.Write "hi/deep/x" "y" }}`,
			"failed to stat hi/deep/x: stat " + disp(filepath.Join(root, "hi", "deep", "x")) + ": not a directory",
		},
		{
			`{{ file.Write "." "y" }}`,
			"failed to write .: open " + disp(root) + ": is a directory",
		},
		{
			`{{ file.Write "empty/" "x" }}`,
			"failed to write empty/: open " + disp(filepath.Join(root, "empty")) + ": is a directory",
		},
	}
	for _, c := range errCases {
		if got := renderErr(t, c.tmpl, "Write"); got != c.want {
			t.Errorf("%s:\n  got  %q\n  want %q", c.tmpl, got, c.want)
		}
	}

	// nothing must have been written outside
	if _, err := os.Stat(filepath.Join(filepath.Dir(root), "escape.txt")); !os.IsNotExist(err) {
		t.Errorf("escape.txt was written outside the working directory")
	}
}

func mustRel(t *testing.T, base, target string) string {
	t.Helper()
	rel, err := filepath.Rel(base, target)
	if err != nil {
		t.Fatal(err)
	}
	return rel
}

func TestArityErrors(t *testing.T) {
	cases := []struct {
		tmpl string
		want string
	}{
		{`{{ file.Read }}`, "wrong number of args for Read: want 1 got 0"},
		{`{{ file.Read "a" "b" }}`, "wrong number of args for Read: want 1 got 2"},
		{`{{ file.Exists }}`, "wrong number of args for Exists: want 1 got 0"},
		{`{{ file.Write }}`, "wrong number of args for Write: want 2 got 0"},
		{`{{ file.Write "onlyone" }}`, "wrong number of args for Write: want 2 got 1"},
	}
	for _, c := range cases {
		_, err := render(t, c.tmpl)
		if err == nil {
			t.Errorf("%s: expected error, got none", c.tmpl)
			continue
		}
		if !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: error %q does not contain %q", c.tmpl, err.Error(), c.want)
		}
	}
}

