package file

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"file": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

// renderErr renders tmpl and returns the portion of the execution error
// after "error calling <name>: ", i.e. the error text returned by the
// function itself.
func renderErr(t *testing.T, tmpl, name string) string {
	t.Helper()
	_, err := render(t, tmpl)
	if err == nil {
		t.Fatalf("expected error rendering %q, got none", tmpl)
	}
	needle := "error calling " + name + ": "
	idx := strings.Index(err.Error(), needle)
	if idx < 0 {
		t.Fatalf("error %q does not contain %q", err.Error(), needle)
	}
	return err.Error()[idx+len(needle):]
}

// disp converts an absolute path to the form the reference tool uses in
// error messages (leading slash stripped).
func disp(p string) string {
	return strings.TrimPrefix(filepath.Clean(p), "/")
}

var root string // fixture directory, used as working directory by all tests

func TestMain(m *testing.M) {
	dir, err := os.MkdirTemp("", "filetest")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	// fixture tree:
	//   hi            "hello world" (no trailing newline)
	//   foo/{a,b,c}   files
	//   foo/d/        directory
	//   foo/sub/{one,two}
	//   foo/link      symlink -> a
	//   dlink         symlink -> foo
	//   broken        symlink -> nonexistent
	//   empty/        empty directory
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(os.WriteFile(filepath.Join(dir, "hi"), []byte("hello world"), 0o644))
	must(os.MkdirAll(filepath.Join(dir, "foo", "sub"), 0o755))
	must(os.MkdirAll(filepath.Join(dir, "foo", "d"), 0o755))
	for _, n := range []string{"a", "b", "c"} {
		must(os.WriteFile(filepath.Join(dir, "foo", n), []byte(n), 0o644))
	}
	must(os.WriteFile(filepath.Join(dir, "foo", "sub", "one"), []byte("1"), 0o644))
	must(os.WriteFile(filepath.Join(dir, "foo", "sub", "two"), []byte("2"), 0o644))
	must(os.Symlink("a", filepath.Join(dir, "foo", "link")))
	must(os.Symlink("foo", filepath.Join(dir, "dlink")))
	must(os.Symlink("nonexistent", filepath.Join(dir, "broken")))
	must(os.MkdirAll(filepath.Join(dir, "empty"), 0o755))

	wd, err := os.Getwd()
	if err != nil {
		panic(err)
	}
	defer os.Chdir(wd)
	must(os.Chdir(dir))
	root = dir

	m.Run()
}

func TestExists(t *testing.T) {
	cases := []struct {
