		{`{{ file.Exists "hi" }}`, "true"},
		{`{{ file.Exists "foo" }}`, "true"},
		{`{{ file.Exists "nope" }}`, "false"},
		{`{{ file.Exists "" }}`, "false"},
		{`{{ file.Exists "hi/" }}`, "true"},
		{`{{ file.Exists "foo/" }}`, "true"},
		{`{{ file.Exists "./hi" }}`, "true"},
		{`{{ file.Exists "foo/../hi" }}`, "true"},
		{`{{ file.Exists "dlink" }}`, "true"},
		{`{{ file.Exists "broken" }}`, "false"},
		{`{{ file.Exists 42 }}`, "false"},
		{`{{ file.Exists true }}`, "false"},
		{`{{ file.Exists 1.5 }}`, "false"},
		{`{{ file.Exists nil }}`, "false"},
		{`{{ "hi" | file.Exists }}`, "true"},
		{`{{ file.Exists (print root "/hi") }}`, "true"},
	}
	for _, c := range cases {
		got, err := render(t, strings.ReplaceAll(c.tmpl, "root", `"`+root+`"`))
