package time

import (
	"bytes"
	stdstrings "strings"
	"testing"
	"text/template"
	stdtime "time"
)

func renderData(t *testing.T, tmpl string, data map[string]any) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"time": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	if data == nil {
		data = map[string]any{}
	}
	data["Env"] = map[string]string{}
	var buf bytes.Buffer
	err = tt.Execute(&buf, data)
	return buf.String(), err
}

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	return renderData(t, tmpl, nil)
}

func TestLayouts(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		want string
	}{
		{"ANSIC", "Mon Jan _2 15:04:05 2006"},
		{"UnixDate", "Mon Jan _2 15:04:05 MST 2006"},
		{"RubyDate", "Mon Jan 02 15:04:05 -0700 2006"},
		{"RFC822", "02 Jan 06 15:04 MST"},
		{"RFC822Z", "02 Jan 06 15:04 -0700"},
		{"RFC850", "Monday, 02-Jan-06 15:04:05 MST"},
		{"RFC1123", "Mon, 02 Jan 2006 15:04:05 MST"},
		{"RFC1123Z", "Mon, 02 Jan 2006 15:04:05 -0700"},
		{"RFC3339", "2006-01-02T15:04:05Z07:00"},
		{"RFC3339Nano", "2006-01-02T15:04:05.999999999Z07:00"},
		{"Kitchen", "3:04PM"},
		{"Stamp", "Jan _2 15:04:05"},
		{"StampMilli", "Jan _2 15:04:05.000"},
		{"StampMicro", "Jan _2 15:04:05.000000"},
		{"StampNano", "Jan _2 15:04:05.000000000"},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, "{{ time."+c.name+" }}")
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("time.%s = %q, want %q", c.name, out, c.want)
			}
		})
	}
}

func TestLayoutNotInvocable(t *testing.T) {
	t.Parallel()
	_, err := render(t, `{{ time.ANSIC "x" }}`)
	if err == nil || !stdstrings.Contains(err.Error(), "ANSIC has arguments but cannot be invoked as function") {
		t.Fatalf("expected not-invocable error, got %v", err)
	}
}

func TestNow(t *testing.T) {
	t.Parallel()
	out, err := render(t, `{{ time.Now | printf "%T" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "time.Time" {
		t.Errorf("time.Now type = %q, want time.Time", out)
	}

	before := stdtime.Now().Unix()
	out, err = render(t, `{{ (time.Now).Unix }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	after := stdtime.Now().Unix()
	var got int64
	if _, err := strconvParseInt(out, &got); err != nil {
		t.Fatalf("parsing %q: %v", out, err)
	}
	if got < before || got > after {
		t.Errorf("time.Now unix %d not in [%d, %d]", got, before, after)
	}
}

func strconvParseInt(s string, out *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errBad
		}
		n = n*10 + int64(c-'0')
	}
	*out = n
	return 0, nil
}

var errBad = stdstrings.NewReplacer().Replace("") // placeholder, replaced below

func TestParse(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string
	}{
		{
			name: "doc example",
			tmpl: `{{ (time.Parse "2006-01-02" "1993-10-23").Format "Monday January 2, 2006 MST" }}`,
			want: "Saturday October 23, 1993 UTC",
		},
		{
			name: "pipeline",
			tmpl: `{{ "1993-10-23" | time.Parse "2006-01-02" }}`,
			want: "1993-10-23 00:00:00 +0000 UTC",
		},
		{
			name: "rfc3339 with zone",
			tmpl: `{{ (time.Parse time.RFC3339 "2020-06-01T10:00:00+02:00").Format "15:04 MST" }}`,
			want: "10:00 +0200",
		},
		{
			name:    "bad timestamp",
			tmpl:    `{{ time.Parse "2006-01-02" "bad" }}`,
			wantErr: `error calling Parse: parsing time "bad" as "2006-01-02": cannot parse "bad" as "2006"`,
		},
		{
			name:    "bad layout mismatch",
			tmpl:    `{{ time.Parse time.RFC3339 "1993-10-23" }}`,
			wantErr: `error calling Parse: parsing time "1993-10-23" as "2006-01-02T15:04:05Z07:00": cannot parse "1993-10-23" as "2006"`,
		},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, c.tmpl)
			if c.wantErr != "" {
				if err == nil || !stdstrings.Contains(err.Error(), c.wantErr) {
					t.Fatalf("error = %v, want substring %q", err, c.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("got %q, want %q", out, c.want)
			}
		})
	}
}

func TestParseLocal(t *testing.T) {
	t.Parallel()
	// with explicit zone, result is independent of the local timezone
	out, err := render(t, `{{ (time.ParseLocal time.RFC3339 "2020-06-01T10:00:00+02:00").Format "15:04 MST" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "10:00 +0200" {
		t.Errorf("got %q, want %q", out, "10:00 +0200")
	}

	// without a zone indicator, the local zone is used
	wantZone, _ := stdtime.Now().Zone()
	out, err = render(t, `{{ (time.ParseLocal "2006-01-02" "1993-10-23").Format "MST" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != wantZone {
		t.Errorf("got zone %q, want local zone %q", out, wantZone)
	}
}

func TestParseInLocation(t *testing.T) {
	t.Parallel()
	out, err := render(t, `{{ (time.ParseInLocation time.Kitchen "UTC" "6:00AM").Format "15:04 MST" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "06:00 UTC" {
		t.Errorf("got %q, want %q", out, "06:00 UTC")
	}

	// pipeline form: timestamp is the final argument
	out, err = render(t, `{{ "6:00AM" | time.ParseInLocation time.Kitchen "UTC" | printf "%T" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "time.Time" {
		t.Errorf("got %q, want time.Time", out)
	}

	_, err = render(t, `{{ time.ParseInLocation time.Kitchen "Bad/Zone" "6:00AM" }}`)
	wantErr := `error calling ParseInLocation: unknown time zone Bad/Zone`
	if err == nil || !stdstrings.Contains(err.Error(), wantErr) {
		t.Fatalf("error = %v, want substring %q", err, wantErr)
	}
}

func TestParseDuration(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string
	}{
		{"compound", `{{ time.ParseDuration "2h30m" }}`, "2h30m0s", ""},
		{"pipeline", `{{ "300ms" | time.ParseDuration }}`, "300ms", ""},
		{"negative float", `{{ time.ParseDuration "-1.5h" }}`, "-1h30m0s", ""},
		{"micro", `{{ time.ParseDuration "1µs" }}`, "1µs", ""},
		{
			name:    "invalid",
			tmpl:    `{{ time.ParseDuration "bad" }}`,
			wantErr: `error calling ParseDuration: time: invalid duration "bad"`,
		},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, c.tmpl)
			if c.wantErr != "" {
				if err == nil || !stdstrings.Contains(err.Error(), c.wantErr) {
					t.Fatalf("error = %v, want substring %q", err, c.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("got %q, want %q", out, c.want)
			}
		})
	}
}

func TestSince(t *testing.T) {
	t.Parallel()
	out, err := render(t, `{{ time.Since (time.Parse time.RFC3339 "1970-01-01T00:00:00Z") | printf "%T" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "time.Duration" {
		t.Errorf("got %q, want time.Duration", out)
	}

	// pipeline form; epoch is ~50+ years ago, so the duration must be huge
	out, err = render(t, `{{ $d := (time.Parse time.RFC3339 "1970-01-01T00:00:00Z") | time.Since }}{{ $d.Hours | printf "%.0f" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out == "" || out == "0" || stdstrings.HasPrefix(out, "-") {
		t.Errorf("time.Since(epoch).Hours = %q, want large positive", out)
	}
}

func TestUntil(t *testing.T) {
	t.Parallel()
	out, err := render(t, `{{ time.Until (time.Parse time.RFC3339 "9999-01-01T00:00:00Z") | printf "%T" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "time.Duration" {
		t.Errorf("got %q, want time.Duration", out)
	}

	// far future: positive; far past: negative
	out, err = render(t, `{{ $d := time.Until (time.Parse time.RFC3339 "9999-01-01T00:00:00Z") }}{{ $d.Hours | printf "%.0f" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out == "" || out == "0" || stdstrings.HasPrefix(out, "-") {
		t.Errorf("time.Until(year 9999).Hours = %q, want large positive", out)
	}

	out, err = render(t, `{{ $d := time.Until (time.Parse time.RFC3339 "1970-01-01T00:00:00Z") }}{{ $d.Hours | printf "%.0f" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !stdstrings.HasPrefix(out, "-") {
		t.Errorf("time.Until(epoch).Hours = %q, want negative", out)
	}
}

func TestUnix(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name    string
		tmpl    string
		data    map[string]any
		want    string
		wantErr string
	}{
		{"whole seconds", `{{ (time.Unix 42).UTC.Format time.Stamp }}`, nil, "Jan  1 00:00:42", ""},
		{"pipeline", `{{ 42 | time.Unix | printf "%T" }}`, nil, "time.Time", ""},
		{"negative", `{{ (time.Unix -42).UTC.Format time.Stamp }}`, nil, "Dec 31 23:59:18", ""},
		{"fractional string", `{{ (time.Unix "123456.789").UTC.Format time.StampMilli }}`, nil, "Jan  2 10:17:36.789", ""},
		{"fractional zero", `{{ (time.Unix "42.0").UTC.Format time.StampMilli }}`, nil, "Jan  1 00:00:42.000", ""},
		{"trailing dot", `{{ (time.Unix "42.").UTC.Format time.Stamp }}`, nil, "Jan  1 00:00:42", ""},
		{"negative fractional", `{{ (time.Unix "-42.5").UTC.Format time.StampMilli }}`, nil, "Dec 31 23:59:18.500", ""},
		{"negative zero fractional", `{{ (time.Unix "-0.5").UTC.Format time.StampMilli }}`, nil, "Jan  1 00:00:00.500", ""},
		{"hex string", `{{ time.Unix "0x10" }}`, nil, "1970-01-01 00:00:16 +0000 UTC", ""},
		{"octal string", `{{ time.Unix "010" }}`, nil, "1970-01-01 00:00:08 +0000 UTC", ""},
		{"binary string", `{{ time.Unix "0b101" }}`, nil, "1970-01-01 00:00:05 +0000 UTC", ""},
		{"fraction truncation", `{{ (time.Unix "42.123456789123").UTC.Format time.StampNano }}`, nil, "Jan  1 00:00:42.123456789", ""},
		{"max int64", `{{ time.Unix "9223372036854775807" }}`, nil, "292277026596-12-04 15:30:07 +0000 UTC", ""},
		{"bool is zero", `{{ time.Unix true }}`, nil, "1970-01-01 00:00:00 +0000 UTC", ""},
		{"nil is zero", `{{ time.Unix .nul }}`, map[string]any{"nul": nil}, "1970-01-01 00:00:00 +0000 UTC", ""},
		{"array is zero", `{{ time.Unix .arr }}`, map[string]any{"arr": []any{1}}, "1970-01-01 00:00:00 +0000 UTC", ""},
		{
			name:    "float literal rejected",
			tmpl:    `{{ time.Unix 42.9 }}`,
			wantErr: `error calling Unix: can not parse floating point number (42.900000) - use a string instead`,
		},
		{
			name:    "float datasource rejected",
			tmpl:    `{{ time.Unix .f }}`,
			data:    map[string]any{"f": 42.5},
