			wantErr: `error calling Unix: strconv.ParseInt: parsing "abc": invalid syntax`,
		},
		{
			name:    "empty string",
			tmpl:    `{{ time.Unix "" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "": invalid syntax`,
		},
		{
			name:    "leading dot",
			tmpl:    `{{ time.Unix ".5" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "": invalid syntax`,
		},
		{
			name:    "spaces not trimmed",
			tmpl:    `{{ time.Unix " 42 " }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing " 42 ": invalid syntax`,
		},
		{
			name:    "exponent rejected",
			tmpl:    `{{ time.Unix "1e3" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "1e3": invalid syntax`,
		},
		{
			name:    "too many decimal points",
			tmpl:    `{{ time.Unix "42.5.6" }}`,
			wantErr: `error calling Unix: can not parse '42.5.6' as a number - too many decimal points`,
		},
		{
			name:    "bad fraction",
			tmpl:    `{{ time.Unix "42.abc" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "abc000000": invalid syntax`,
		},
		{
			name:    "fraction with exponent",
			tmpl:    `{{ time.Unix "42.12e3" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "12e300000": invalid syntax`,
		},
		{
			name:    "fraction leading zero octal error",
			tmpl:    `{{ time.Unix "42.0789" }}`,
			wantErr: `error calling Unix: strconv.ParseInt: parsing "078900000": invalid syntax`,
		},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := renderData(t, c.tmpl, c.data)
			if c.wantErr != "" {
				if err == nil || !stdstrings.Contains(err.Error(), c.wantErr) {
					t.Fatalf("error = %v, want substring %q", err, c.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("got %q, want %q", out, c.want)
			}
		})
	}
}

