func TestZoneNameOffset(t *testing.T) {
	t.Parallel()
	wantName, wantOffset := stdtime.Now().Zone()

	out, err := render(t, `{{ time.ZoneName }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != wantName {
		t.Errorf("ZoneName = %q, want %q", out, wantName)
	}

	out, err = render(t, `{{ time.ZoneOffset }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != strconvI64(int64(wantOffset)) {
		t.Errorf("ZoneOffset = %q, want %d", out, wantOffset)
	}
}

func strconvI64(i int64) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b [20]byte
	pos := len(b)
	for i > 0 {
		pos--
		b[pos] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		pos--
		b[pos] = '-'
	}
	return string(b[pos:])
}

func TestDurationDocExampleShape(t *testing.T) {
	t.Parallel()
	// the doc combines Hour with Time.Add; verify the types compose
