package time

import (
	"bytes"
	stdstrings "strings"
	"testing"
	"text/template"
	stdtime "time"
)

func renderData(t *testing.T, tmpl string, data map[string]any) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"time": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	if data == nil {
		data = map[string]any{}
	}
	data["Env"] = map[string]string{}
	var buf bytes.Buffer
	err = tt.Execute(&buf, data)
	return buf.String(), err
}

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	return renderData(t, tmpl, nil)
}

func TestLayouts(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		want string
	}{
		{"ANSIC", "Mon Jan _2 15:04:05 2006"},
		{"UnixDate", "Mon Jan _2 15:04:05 MST 2006"},
		{"RubyDate", "Mon Jan 02 15:04:05 -0700 2006"},
		{"RFC822", "02 Jan 06 15:04 MST"},
		{"RFC822Z", "02 Jan 06 15:04 -0700"},
		{"RFC850", "Monday, 02-Jan-06 15:04:05 MST"},
		{"RFC1123", "Mon, 02 Jan 2006 15:04:05 MST"},
		{"RFC1123Z", "Mon, 02 Jan 2006 15:04:05 -0700"},
		{"RFC3339", "2006-01-02T15:04:05Z07:00"},
		{"RFC3339Nano", "2006-01-02T15:04:05.999999999Z07:00"},
		{"Kitchen", "3:04PM"},
		{"Stamp", "Jan _2 15:04:05"},
		{"StampMilli", "Jan _2 15:04:05.000"},
		{"StampMicro", "Jan _2 15:04:05.000000"},
		{"StampNano", "Jan _2 15:04:05.000000000"},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, "{{ time."+c.name+" }}")
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("time.%s = %q, want %q", c.name, out, c.want)
			}
		})
	}
}

func TestLayoutNotInvocable(t *testing.T) {
	t.Parallel()
	_, err := render(t, `{{ time.ANSIC "x" }}`)
	if err == nil || !stdstrings.Contains(err.Error(), "ANSIC has arguments but cannot be invoked as function") {
		t.Fatalf("expected not-invocable error, got %v", err)
	}
}

func TestNow(t *testing.T) {
	t.Parallel()
	out, err := render(t, `{{ time.Now | printf "%T" }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if out != "time.Time" {
		t.Errorf("time.Now type = %q, want time.Time", out)
	}

	before := stdtime.Now().Unix()
	out, err = render(t, `{{ (time.Now).Unix }}`)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	after := stdtime.Now().Unix()
	var got int64
	if _, err := strconvParseInt(out, &got); err != nil {
		t.Fatalf("parsing %q: %v", out, err)
	}
	if got < before || got > after {
		t.Errorf("time.Now unix %d not in [%d, %d]", got, before, after)
	}
}

func strconvParseInt(s string, out *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errBad
		}
		n = n*10 + int64(c-'0')
	}
	*out = n
	return 0, nil
}

var errBad = stdstrings.NewReplacer().Replace("") // placeholder, replaced below

func TestParse(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name    string
		tmpl    string
		want    string
		wantErr string
	}{
		{
			name: "doc example",
			tmpl: `{{ (time.Parse "2006-01-02" "1993-10-23").Format "Monday January 2, 2006 MST" }}`,
			want: "Saturday October 23, 1993 UTC",
		},
		{
			name: "pipeline",
			tmpl: `{{ "1993-10-23" | time.Parse "2006-01-02" }}`,
			want: "1993-10-23 00:00:00 +0000 UTC",
		},
		{
			name: "rfc3339 with zone",
			tmpl: `{{ (time.Parse time.RFC3339 "2020-06-01T10:00:00+02:00").Format "15:04 MST" }}`,
			want: "10:00 +0200",
		},
		{
			name:    "bad timestamp",
			tmpl:    `{{ time.Parse "2006-01-02" "bad" }}`,
			wantErr: `error calling Parse: parsing time "bad" as "2006-01-02": cannot parse "bad" as "2006"`,
		},
		{
			name:    "bad layout mismatch",
			tmpl:    `{{ time.Parse time.RFC3339 "1993-10-23" }}`,
			wantErr: `error calling Parse: parsing time "1993-10-23" as "2006-01-02T15:04:05Z07:00": cannot parse "1993-10-23" as "2006"`,
		},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, c.tmpl)
			if c.wantErr != "" {
				if err == nil || !stdstrings.Contains(err.Error(), c.wantErr) {
					t.Fatalf("error = %v, want substring %q", err, c.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
