package main

import (
	"encoding/json"
	"fmt"
	"os/exec"
	"strings"
)

func binErr(tmpl string) string {
	cmd := exec.Command("/workspace/executable", "-i", tmpl)
	var out, errb strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = &errb
	cmd.Run()
	if errb.Len() == 0 {
		return "STDOUT:" + out.String()
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(strings.TrimSpace(errb.String())), &m); err != nil {
		return "PARSEFAIL:" + errb.String()
	}
	return fmt.Sprintf("%v", m["err"])
}

func main() {
	cases := [][2]string{
		{`{{ conv.ToInt64 "blah" }}`, `could not convert "blah" to int64: strconv.ParseFloat: parsing "blah": invalid syntax`},
		{`{{ conv.ToInt64 (dict "a" 1) }}`, `could not convert map[a:1] to int64`},
		{`{{ conv.ToInt64 nil }}`, `could not convert <nil> to int64`},
		{`{{ conv.ToInt64 "9,99x" }}`, `could not convert "999x" to int64: strconv.ParseFloat: parsing "999x": invalid syntax`},
		{`{{ conv.ToFloat64 "blah" }}`, `could not convert "blah" to float64: strconv.ParseFloat: parsing "blah": invalid syntax`},
		{`{{ conv.ToInt "abc" }}`, `could not convert "abc" to int64: strconv.ParseFloat: parsing "abc": invalid syntax`},
		{`{{ join "x" "-" }}`, `input to Join must be an array: expected an array or slice, but got a reflect.Value`},
		{`{{ conv.URL "%%%" }}`, `parse "%%%": invalid URL escape "%%%"`},
		{`{{ conv.Atoi "abc" }}`, `strconv.Atoi: parsing "abc": invalid syntax`},
		{`{{ conv.ParseInt "zz" 16 64 }}`, `strconv.ParseInt: parsing "zz": invalid syntax`},
		{`{{ conv.ParseFloat "zz" 64 }}`, `strconv.ParseFloat: parsing "zz": invalid syntax`},
		{`{{ conv.ParseUint "-1" 10 64 }}`, `strconv.ParseUint: parsing "-1": invalid syntax`},
	}
	bad := 0
	for _, c := range cases {
		err := binErr(c[0])
		idx := strings.Index(err, "error calling ")
		if idx < 0 {
			fmt.Println("NO-ERR-CALL:", c[0], "=>", err)
			bad++
			continue
		}
		rest := err[idx+len("error calling "):]
		parts := strings.SplitN(rest, ": ", 2)
		if len(parts) < 2 || parts[1] != c[1] {
			fmt.Printf("MISMATCH: %s\n  got  %q\n  want %q\n", c[0], rest, c[1])
			bad++
		}
	}
	if bad == 0 {
		fmt.Println("ALL ERROR TEXTS MATCH")
	}
}
EOF
